import{_ as t,c as a,o as i,a2 as o}from"./chunks/framework.B7el9cAC.js";const u=JSON.parse('{"title":"Mục 4.1 – Cơ Sở Dữ Liệu (CSDL) và DBMS","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-4/4.1-csld-dbms.md","filePath":"chuong-4/4.1-csld-dbms.md","lastUpdated":1775361516000}'),h={name:"chuong-4/4.1-csld-dbms.md"};function e(r,n,c,g,l,d){return i(),a("div",null,[...n[0]||(n[0]=[o('<h1 id="muc-4-1-–-co-so-du-lieu-csdl-va-dbms" tabindex="-1">Mục 4.1 – Cơ Sở Dữ Liệu (CSDL) và DBMS <a class="header-anchor" href="#muc-4-1-–-co-so-du-lieu-csdl-va-dbms" aria-label="Permalink to &quot;Mục 4.1 – Cơ Sở Dữ Liệu (CSDL) và DBMS&quot;">​</a></h1><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><h3 id="tai-sao-can-csdl" tabindex="-1">Tại sao cần CSDL? <a class="header-anchor" href="#tai-sao-can-csdl" aria-label="Permalink to &quot;Tại sao cần CSDL?&quot;">​</a></h3><p>Hãy tưởng tượng bạn đang quản lý một <strong>quán cafe nhỏ</strong>. Ban đầu bạn chỉ có 10 khách hàng, bạn ghi tên và số điện thoại của họ vào một tờ giấy. Ổn thôi.</p><p>Nhưng sau 1 năm, quán bạn có <strong>5.000 khách hàng thân thiết</strong>, mỗi người có lịch sử đặt hàng, điểm thưởng, địa chỉ giao hàng... Bạn không thể dùng tờ giấy nữa. Bạn chuyển sang Excel — nhưng rồi có 3 nhân viên cùng sửa file cùng lúc, dữ liệu bị xung đột, bị mất...</p><p><strong>Đây chính là lúc bạn cần Cơ Sở Dữ Liệu (CSDL).</strong></p><p>Vài ví dụ quen thuộc trong cuộc sống:</p><ul><li>🏫 <strong>Trường học</strong>: lưu danh sách học sinh, điểm thi, thời khóa biểu</li><li>🏥 <strong>Bệnh viện</strong>: lưu hồ sơ bệnh nhân, lịch khám, đơn thuốc</li><li>🏦 <strong>Ngân hàng</strong>: lưu tài khoản, lịch sử giao dịch, số dư</li></ul><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="_2-1-co-so-du-lieu-csdl-la-gi" tabindex="-1">2.1 Cơ Sở Dữ Liệu (CSDL) là gì? <a class="header-anchor" href="#_2-1-co-so-du-lieu-csdl-la-gi" aria-label="Permalink to &quot;2.1 Cơ Sở Dữ Liệu (CSDL) là gì?&quot;">​</a></h3><blockquote><p><strong>Định nghĩa:</strong> Cơ sở dữ liệu (Database) là một tập hợp dữ liệu có tổ chức, được lưu trữ và quản lý trên máy tính, cho phép truy xuất, cập nhật và xử lý một cách hiệu quả.</p></blockquote><p>Các đặc điểm của CSDL:</p><ul><li><strong>Có cấu trúc rõ ràng</strong>: dữ liệu được tổ chức thành bảng (table), hàng (row), cột (column)</li><li><strong>Không trùng lặp</strong>: dữ liệu được lưu một lần, dùng nhiều nơi</li><li><strong>Nhất quán</strong>: nhiều người dùng cùng thấy dữ liệu giống nhau</li><li><strong>Bảo mật</strong>: phân quyền truy cập cho từng người dùng</li></ul><h3 id="_2-2-dbms-la-gi" tabindex="-1">2.2 DBMS là gì? <a class="header-anchor" href="#_2-2-dbms-la-gi" aria-label="Permalink to &quot;2.2 DBMS là gì?&quot;">​</a></h3><blockquote><p><strong>Định nghĩa:</strong> DBMS (Database Management System – Hệ quản trị cơ sở dữ liệu) là <strong>phần mềm trung gian</strong> giúp người dùng tạo, truy xuất, cập nhật và quản lý CSDL.</p></blockquote><p>Các DBMS phổ biến:</p><table tabindex="0"><thead><tr><th>Tên DBMS</th><th>Loại</th><th>Ứng dụng điển hình</th></tr></thead><tbody><tr><td>MySQL</td><td>Miễn phí, mã nguồn mở</td><td>Web, ứng dụng vừa và nhỏ</td></tr><tr><td>PostgreSQL</td><td>Miễn phí, mã nguồn mở</td><td>Hệ thống phức tạp, dữ liệu lớn</td></tr><tr><td>Microsoft SQL Server</td><td>Thương mại</td><td>Doanh nghiệp lớn</td></tr><tr><td>SQLite</td><td>Nhúng, nhẹ</td><td>Ứng dụng di động, desktop</td></tr><tr><td>Oracle</td><td>Thương mại</td><td>Ngân hàng, tập đoàn lớn</td></tr></tbody></table><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="thuc-chat-csdl-la-gi" tabindex="-1">Thực chất CSDL là gì? <a class="header-anchor" href="#thuc-chat-csdl-la-gi" aria-label="Permalink to &quot;Thực chất CSDL là gì?&quot;">​</a></h3><p>Hãy hình dung CSDL như một <strong>tủ hồ sơ thông minh</strong> trong văn phòng:</p><ul><li>Mỗi <strong>ngăn kéo</strong> = một <strong>bảng (table)</strong></li><li>Mỗi <strong>tờ hồ sơ</strong> trong ngăn kéo = một <strong>hàng (row) / bản ghi (record)</strong></li><li>Mỗi <strong>mục thông tin</strong> trên tờ hồ sơ (họ tên, ngày sinh...) = một <strong>cột (column) / trường (field)</strong></li></ul><p>Còn <strong>DBMS</strong> chính là <strong>người thư ký</strong> biết cách:</p><ul><li>Tìm đúng hồ sơ bạn cần trong vài giây (dù có hàng triệu hồ sơ)</li><li>Đảm bảo 10 người cùng đọc hồ sơ mà không ai làm hỏng dữ liệu của người kia</li><li>Từ chối lưu hồ sơ bị thiếu thông tin quan trọng</li></ul><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><p>Khi một học sinh đăng nhập vào hệ thống tra cứu điểm của trường:</p><p><strong>Bước 1:</strong> Học sinh nhập mã số học sinh vào ứng dụng web.</p><p><strong>Bước 2:</strong> Ứng dụng gửi yêu cầu đến DBMS bằng câu lệnh SQL: <em>&quot;Tìm điểm thi của học sinh có mã số này.&quot;</em></p><p><strong>Bước 3:</strong> DBMS kiểm tra quyền truy cập — học sinh này có được xem dữ liệu không?</p><p><strong>Bước 4:</strong> DBMS tìm kiếm trong CSDL, định vị đúng bảng <code>DiemThi</code>, lọc theo mã học sinh.</p><p><strong>Bước 5:</strong> DBMS trả kết quả về cho ứng dụng.</p><p><strong>Bước 6:</strong> Ứng dụng hiển thị bảng điểm lên màn hình cho học sinh xem.</p><blockquote><p>💡 Toàn bộ quá trình này diễn ra trong <strong>chưa đầy 1 giây</strong>, dù trường có 10.000 học sinh.</p></blockquote><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-nha-ban-quan-ly-chi-tieu" tabindex="-1">Ví dụ 1 – Cơ bản: Nhà bạn quản lý chi tiêu <a class="header-anchor" href="#vi-du-1-–-co-ban-nha-ban-quan-ly-chi-tieu" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: Nhà bạn quản lý chi tiêu&quot;">​</a></h3><p>Bạn tạo một CSDL nhỏ gồm 1 bảng:</p><table tabindex="0"><thead><tr><th>MaChiTieu</th><th>NgayMua</th><th>MoTa</th><th>SoTien</th></tr></thead><tbody><tr><td>1</td><td>2024-01-05</td><td>Mua sách</td><td>85000</td></tr><tr><td>2</td><td>2024-01-06</td><td>Ăn sáng</td><td>30000</td></tr><tr><td>3</td><td>2024-01-07</td><td>Xe buýt</td><td>10000</td></tr></tbody></table><p>Đây là CSDL đơn giản nhất — 1 bảng, vài cột, vài hàng.</p><hr><h3 id="vi-du-2-–-thuc-te-quan-cafe" tabindex="-1">Ví dụ 2 – Thực tế: Quán cafe <a class="header-anchor" href="#vi-du-2-–-thuc-te-quan-cafe" aria-label="Permalink to &quot;Ví dụ 2 – Thực tế: Quán cafe&quot;">​</a></h3><p>Quán cafe &quot;Cà Phê Mộc&quot; có 3 bảng:</p><p><strong>Bảng KhachHang:</strong></p><table tabindex="0"><thead><tr><th>MaKH</th><th>HoTen</th><th>SoDienThoai</th></tr></thead><tbody><tr><td>KH001</td><td>Nguyễn An</td><td>0901234567</td></tr><tr><td>KH002</td><td>Trần Bình</td><td>0912345678</td></tr></tbody></table><p><strong>Bảng SanPham:</strong></p><table tabindex="0"><thead><tr><th>MaSP</th><th>TenSP</th><th>Gia</th></tr></thead><tbody><tr><td>SP01</td><td>Cà phê sữa</td><td>35000</td></tr><tr><td>SP02</td><td>Trà đào</td><td>45000</td></tr></tbody></table><p><strong>Bảng DonHang:</strong></p><table tabindex="0"><thead><tr><th>MaDon</th><th>MaKH</th><th>MaSP</th><th>SoLuong</th><th>NgayDat</th></tr></thead><tbody><tr><td>DH001</td><td>KH001</td><td>SP01</td><td>2</td><td>2024-03-01</td></tr><tr><td>DH002</td><td>KH002</td><td>SP02</td><td>1</td><td>2024-03-01</td></tr></tbody></table><blockquote><p>✅ Mỗi bảng lưu một loại thông tin. Chúng liên kết với nhau qua mã (MaKH, MaSP).</p></blockquote><hr><h3 id="vi-du-3-–-nang-cao-truong-hoc-voi-nhieu-bang" tabindex="-1">Ví dụ 3 – Nâng cao: Trường học với nhiều bảng <a class="header-anchor" href="#vi-du-3-–-nang-cao-truong-hoc-voi-nhieu-bang" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: Trường học với nhiều bảng&quot;">​</a></h3><p>Hệ thống trường học điển hình có thể có 10+ bảng: <code>HocSinh</code>, <code>GiaoVien</code>, <code>Lop</code>, <code>MonHoc</code>, <code>DiemThi</code>, <code>ThoiKhoaBieu</code>, <code>PhongHoc</code>...</p><p>Mỗi bảng lưu đúng việc của nó. Khi cần báo cáo tổng hợp, DBMS sẽ <strong>kết nối</strong> các bảng lại theo yêu cầu.</p><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="csdl-vs-file-excel" tabindex="-1">CSDL vs. File Excel <a class="header-anchor" href="#csdl-vs-file-excel" aria-label="Permalink to &quot;CSDL vs. File Excel&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>File Excel</th><th>Cơ Sở Dữ Liệu (CSDL)</th></tr></thead><tbody><tr><td>Số lượng dữ liệu</td><td>Vài nghìn dòng (chậm nếu nhiều hơn)</td><td>Hàng triệu, hàng tỷ bản ghi</td></tr><tr><td>Nhiều người dùng cùng lúc</td><td>Dễ xung đột, mất dữ liệu</td><td>Xử lý đồng thời an toàn</td></tr><tr><td>Tìm kiếm / lọc</td><td>Chậm, thủ công</td><td>Rất nhanh với chỉ mục (index)</td></tr><tr><td>Bảo mật</td><td>Chỉ có mật khẩu file</td><td>Phân quyền chi tiết từng bảng, từng cột</td></tr><tr><td>Liên kết dữ liệu</td><td>Dùng VLOOKUP phức tạp</td><td>Khóa ngoại tự động, chính xác</td></tr><tr><td>Tự động hóa</td><td>Hạn chế (macro)</td><td>Triggers, stored procedures</td></tr><tr><td>Khôi phục dữ liệu</td><td>Khó</td><td>Backup &amp; restore chuyên nghiệp</td></tr></tbody></table><h3 id="dbms-vs-csdl" tabindex="-1">DBMS vs. CSDL <a class="header-anchor" href="#dbms-vs-csdl" aria-label="Permalink to &quot;DBMS vs. CSDL&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>CSDL</th><th>DBMS</th></tr></thead><tbody><tr><td>Là gì?</td><td>Tập hợp dữ liệu</td><td>Phần mềm quản lý</td></tr><tr><td>Ví dụ</td><td>Dữ liệu học sinh trường THPT X</td><td>MySQL, PostgreSQL</td></tr><tr><td>Vai trò</td><td>Nơi lưu trữ</td><td>Công cụ truy xuất và quản lý</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>📌 <strong>CSDL</strong> = tập hợp dữ liệu có tổ chức, lưu trên máy tính</li><li>📌 <strong>DBMS</strong> = phần mềm quản lý CSDL (MySQL, PostgreSQL, Oracle...)</li><li>📌 Cấu trúc cơ bản: <strong>Bảng (Table)</strong> → <strong>Hàng (Row/Record)</strong> → <strong>Cột (Column/Field)</strong></li><li>📌 CSDL <strong>hơn Excel</strong> ở: nhiều người dùng, dữ liệu lớn, bảo mật, liên kết bảng</li><li>📌 DBMS đóng vai trò <strong>trung gian</strong> giữa người dùng và dữ liệu</li><li>📌 Các DBMS phổ biến cần nhớ: <strong>MySQL, PostgreSQL, SQL Server, SQLite, Oracle</strong></li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><p><strong>Câu 1 (Dễ):</strong> CSDL là gì? Hãy nêu 2 đặc điểm của CSDL.</p><blockquote><p><strong>Đáp án:</strong> CSDL là tập hợp dữ liệu có tổ chức lưu trên máy tính. Hai đặc điểm: (1) Dữ liệu có cấu trúc rõ ràng (bảng, hàng, cột). (2) Dữ liệu không trùng lặp, nhất quán.</p></blockquote><hr><p><strong>Câu 2 (Dễ):</strong> Kể tên 3 phần mềm DBMS phổ biến và nêu 1 ứng dụng thực tế của mỗi phần mềm đó.</p><blockquote><p><strong>Đáp án:</strong> MySQL (website thương mại điện tử), PostgreSQL (hệ thống phân tích dữ liệu lớn), SQLite (ứng dụng di động).</p></blockquote><hr><p><strong>Câu 3 (Trung bình):</strong> Tại sao một trường học với 5.000 học sinh nên dùng CSDL thay vì quản lý bằng file Excel? Nêu ít nhất 3 lý do cụ thể.</p><blockquote><p><strong>Đáp án:</strong> (1) Nhiều giáo viên, nhân viên có thể truy cập cùng lúc mà không gây xung đột. (2) Tìm kiếm học sinh, lọc điểm nhanh hơn nhiều nhờ chỉ mục. (3) Phân quyền: giáo viên chỉ xem điểm lớp mình, học sinh chỉ xem điểm của mình.</p></blockquote><hr><p><strong>Câu 4 (Trung bình):</strong> Phân biệt CSDL và DBMS. Cho ví dụ cụ thể.</p><blockquote><p><strong>Đáp án:</strong> CSDL là <em>nơi chứa dữ liệu</em> (ví dụ: toàn bộ thông tin học sinh của trường). DBMS là <em>phần mềm</em> dùng để tạo, truy xuất và quản lý CSDL đó (ví dụ: MySQL). Mối quan hệ: DBMS là công cụ, CSDL là kho chứa dữ liệu mà DBMS quản lý.</p></blockquote><hr><p><strong>Câu 5 (Vận dụng):</strong> Một bệnh viện muốn xây dựng hệ thống quản lý bệnh nhân. Hãy đề xuất ít nhất 4 bảng (table) cần có trong CSDL và nêu 2–3 cột quan trọng của mỗi bảng.</p><blockquote><p><strong>Đáp án gợi ý:</strong></p><ul><li>Bảng <code>BenhNhan</code>: MaBN, HoTen, NgaySinh, SoDienThoai</li><li>Bảng <code>BacSi</code>: MaBS, HoTen, ChuyenKhoa, SoDienThoai</li><li>Bảng <code>LichKham</code>: MaLich, MaBN, MaBS, NgayKham, ChanDoan</li><li>Bảng <code>DonThuoc</code>: MaDon, MaLich, TenThuoc, LieuLuong, SoNgayDung</li></ul></blockquote><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><h3 id="❌-loi-1-nham-csdl-voi-dbms" tabindex="-1">❌ Lỗi 1: Nhầm CSDL với DBMS <a class="header-anchor" href="#❌-loi-1-nham-csdl-voi-dbms" aria-label="Permalink to &quot;❌ Lỗi 1: Nhầm CSDL với DBMS&quot;">​</a></h3><p><strong>Sai:</strong> &quot;MySQL là cơ sở dữ liệu của tôi.&quot;</p><p><strong>Đúng:</strong> MySQL là <strong>DBMS (phần mềm quản trị CSDL)</strong>. Cơ sở dữ liệu (CSDL) là tập hợp dữ liệu thực sự bên trong (các bảng, rows, columns). MySQL là công cụ để tạo và quản lý CSDL, không phải CSDL. Tương tự: Word là phần mềm, file .docx là tài liệu.</p><hr><h3 id="❌-loi-2-tao-qua-nhieu-cot-trong-mot-bang" tabindex="-1">❌ Lỗi 2: Tạo quá nhiều cột trong một bảng <a class="header-anchor" href="#❌-loi-2-tao-qua-nhieu-cot-trong-mot-bang" aria-label="Permalink to &quot;❌ Lỗi 2: Tạo quá nhiều cột trong một bảng&quot;">​</a></h3><p><strong>Sai:</strong> Bảng <code>HoSo</code> có 50 cột: tên, địa chỉ, điện thoại, ngày sinh, tên cha, điện thoại cha, tên mẹ, điện thoại mẹ, điểm toán, điểm văn...</p><p><strong>Đúng:</strong> Tách thành nhiều bảng theo nguyên tắc mỗi bảng một chủ đề: <code>HocSinh</code>, <code>PhuHuynh</code>, <code>DiemHoc</code>. Bảng lớn vi phạm normalization, gây: lưu dữ liệu trùng lặp, khó update, và hiệu suất kém.</p><hr><h3 id="❌-loi-3-luu-du-lieu-trung-lap" tabindex="-1">❌ Lỗi 3: Lưu dữ liệu trùng lặp <a class="header-anchor" href="#❌-loi-3-luu-du-lieu-trung-lap" aria-label="Permalink to &quot;❌ Lỗi 3: Lưu dữ liệu trùng lặp&quot;">​</a></h3><p><strong>Sai:</strong> Lưu tên giáo viên vào mỗi bảng <code>LopHoc</code>, <code>DiemSo</code>, <code>ThoiKhoaBieu</code> – khi thầy đổi tên phải update nhiều chỗ.</p><p><strong>Đúng:</strong> Dùng bảng riêng <code>GiaoVien</code> với <code>MaGV</code> là Primary Key. Các bảng khác chỉ lưu <code>MaGV</code> làm Foreign Key. Thay tên chỉ cần update một chỗ trong bảng <code>GiaoVien</code>.</p><hr><h3 id="❌-loi-4-khong-đat-primary-key" tabindex="-1">❌ Lỗi 4: Không đặt Primary Key <a class="header-anchor" href="#❌-loi-4-khong-đat-primary-key" aria-label="Permalink to &quot;❌ Lỗi 4: Không đặt Primary Key&quot;">​</a></h3><p><strong>Sai:</strong> Bảng <code>SanPham</code> không có cột khóa chính, chỉ có tên và giá.</p><p><strong>Đúng:</strong> Mỗi bảng cần khóa chính (Primary Key) để xác định duy nhất mỗi hàng. Không có PK: không thể phân biệt hai sản phẩm cùng tên khác loại, không thể tạo Foreign Key từ bảng khác trỏ vào.</p><hr><h3 id="❌-loi-5-nghi-csdl-chi-dung-cho-doanh-nghiep-lon" tabindex="-1">❌ Lỗi 5: Nghĩ CSDL chỉ dùng cho doanh nghiệp lớn <a class="header-anchor" href="#❌-loi-5-nghi-csdl-chi-dung-cho-doanh-nghiep-lon" aria-label="Permalink to &quot;❌ Lỗi 5: Nghĩ CSDL chỉ dùng cho doanh nghiệp lớn&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dự án nhỏ chỉ cần lưu file Excel là đủ, không cần CSDL.&quot;</p><p><strong>Đúng:</strong> SQLite là CSDL nhẹ không cần server, phù hợp ngay cả cho app cá nhân. CSDL giúp: truy vấn nhanh hơn, tránh trùng lặp, hỗ trợ đồng thời nhiều người dùng, và dễ mở rộng. File Excel không đảm bảo tính toàn vẹn dữ liệu (không có constraints).</p><hr><h3 id="❌-loi-6-nham-row-hang-voi-record-va-column-voi-field" tabindex="-1">❌ Lỗi 6: Nhầm row (hàng) với record và column với field <a class="header-anchor" href="#❌-loi-6-nham-row-hang-voi-record-va-column-voi-field" aria-label="Permalink to &quot;❌ Lỗi 6: Nhầm row (hàng) với record và column với field&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Bảng có 5 cột và 100 hàng, nhưng tôi không chắc record là gì.&quot;</p><p><strong>Đúng:</strong> Row = record = bản ghi = một dòng dữ liệu (ví dụ: thông tin một học sinh). Column = field = trường = một thuộc tính (ví dụ: họ tên). Đây là các thuật ngữ đồng nghĩa. Nắm rõ để không bị nhầm khi đọc tài liệu.</p><hr><h3 id="❌-loi-7-nghi-csdl-quan-he-la-loai-csdl-duy-nhat" tabindex="-1">❌ Lỗi 7: Nghĩ CSDL quan hệ là loại CSDL duy nhất <a class="header-anchor" href="#❌-loi-7-nghi-csdl-quan-he-la-loai-csdl-duy-nhat" aria-label="Permalink to &quot;❌ Lỗi 7: Nghĩ CSDL quan hệ là loại CSDL duy nhất&quot;">​</a></h3><p><strong>Sai:</strong> &quot;CSDL = CSDL quan hệ, không có loại nào khác.&quot;</p><p><strong>Đúng:</strong> Ngoài CSDL quan hệ (MySQL, PostgreSQL, SQLite), còn có: NoSQL document stores (MongoDB – lưu JSON), key-value stores (Redis), graph databases (Neo4j), và columnar databases (Cassandra). Mỗi loại phù hợp với usecase khác nhau.</p><hr><h3 id="❌-loi-8-nham-schema-voi-database" tabindex="-1">❌ Lỗi 8: Nhầm schema với database <a class="header-anchor" href="#❌-loi-8-nham-schema-voi-database" aria-label="Permalink to &quot;❌ Lỗi 8: Nhầm schema với database&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Schema là một từ khác của database.&quot;</p><p><strong>Đúng:</strong> Schema là cấu trúc logic của database: tên bảng, tên cột, kiểu dữ liệu, quan hệ, constraints. Database là cả schema lẫn dữ liệu thực tế. Schema như bản vẽ nhà, database như ngôi nhà đã xây với đầy đủ đồ đạc bên trong.</p><hr><h3 id="❌-loi-9-cho-rang-luu-so-đien-thoai-dang-so-nguyen-la-đung" tabindex="-1">❌ Lỗi 9: Cho rằng lưu số điện thoại dạng số nguyên là đúng <a class="header-anchor" href="#❌-loi-9-cho-rang-luu-so-đien-thoai-dang-so-nguyen-la-đung" aria-label="Permalink to &quot;❌ Lỗi 9: Cho rằng lưu số điện thoại dạng số nguyên là đúng&quot;">​</a></h3><p><strong>Sai:</strong> <code>SoDienThoai INT</code> – lưu 0123456789 thành số nguyên.</p><p><strong>Đúng:</strong> Số điện thoại nên là <code>VARCHAR</code> vì: có thể bắt đầu bằng 0 (bị mất nếu là INT), có thể có ký tự đặc biệt (+84, dấu gạch nối), và phép tính số học không có ý nghĩa với SĐT. Quy tắc: nếu không cần tính toán, lưu dạng text.</p><hr><h3 id="❌-loi-10-nghi-null-co-nghia-la-0-hoac-chuoi-rong" tabindex="-1">❌ Lỗi 10: Nghĩ NULL có nghĩa là 0 hoặc chuỗi rỗng <a class="header-anchor" href="#❌-loi-10-nghi-null-co-nghia-la-0-hoac-chuoi-rong" aria-label="Permalink to &quot;❌ Lỗi 10: Nghĩ NULL có nghĩa là 0 hoặc chuỗi rỗng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Cột có giá trị NULL tức là bằng 0.&quot;</p><p><strong>Đúng:</strong> NULL có nghĩa là &quot;không biết&quot; hoặc &quot;không có giá trị&quot; – khác với 0 (biết là 0) hay &#39;&#39; (biết là chuỗi rỗng). NULL + bất kỳ = NULL. NULL = NULL trả về FALSE (phải dùng IS NULL). Hiểu sai NULL gây lỗi khó tìm.</p><hr><h3 id="❌-loi-11-nham-index-voi-primary-key" tabindex="-1">❌ Lỗi 11: Nhầm index với Primary Key <a class="header-anchor" href="#❌-loi-11-nham-index-voi-primary-key" aria-label="Permalink to &quot;❌ Lỗi 11: Nhầm index với Primary Key&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Đã có Primary Key rồi thì không cần thêm index nào nữa.&quot;</p><p><strong>Đúng:</strong> PK tự động tạo index trên cột PK. Nhưng khi truy vấn theo cột khác thường xuyên (ví dụ: WHERE ho_ten = &#39;Nam&#39;), cần tạo thêm index riêng. Index tăng tốc SELECT nhưng làm chậm INSERT/UPDATE. Cân bằng theo pattern truy vấn thực tế.</p><hr><h3 id="❌-loi-12-cho-rang-csdl-khong-can-backup" tabindex="-1">❌ Lỗi 12: Cho rằng CSDL không cần backup <a class="header-anchor" href="#❌-loi-12-cho-rang-csdl-khong-can-backup" aria-label="Permalink to &quot;❌ Lỗi 12: Cho rằng CSDL không cần backup&quot;">​</a></h3><p><strong>Sai:</strong> &quot;CSDL trên server cloud sẽ không bao giờ mất dữ liệu.&quot;</p><p><strong>Đúng:</strong> Cloud không đảm bảo không mất dữ liệu: human error (xóa nhầm), ransomware, provider outage. Quy tắc 3-2-1: 3 bản sao, 2 loại media khác nhau, 1 bản offsite. Test backup restore định kỳ – backup không test là không tin được.</p><hr><h3 id="❌-loi-13-nghi-transaction-chi-dung-cho-ngan-hang" tabindex="-1">❌ Lỗi 13: Nghĩ transaction chỉ dùng cho ngân hàng <a class="header-anchor" href="#❌-loi-13-nghi-transaction-chi-dung-cho-ngan-hang" aria-label="Permalink to &quot;❌ Lỗi 13: Nghĩ transaction chỉ dùng cho ngân hàng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Transaction (giao dịch) chỉ cần cho hệ thống tài chính.&quot;</p><p><strong>Đúng:</strong> Transaction đảm bảo ACID (Atomicity, Consistency, Isolation, Durability) – cần cho mọi thao tác liên quan đến nhiều bảng. Ví dụ: đặt hàng online cần: trừ inventory + tạo order + tạo payment – nếu một bước lỗi, phải rollback tất cả. Không chỉ dành cho tài chính.</p><hr><h3 id="❌-loi-14-nham-delete-voi-drop" tabindex="-1">❌ Lỗi 14: Nhầm DELETE với DROP <a class="header-anchor" href="#❌-loi-14-nham-delete-voi-drop" aria-label="Permalink to &quot;❌ Lỗi 14: Nhầm DELETE với DROP&quot;">​</a></h3><p><strong>Sai:</strong> <code>DROP TABLE SanPham</code> để xóa sản phẩm này.</p><p><strong>Đúng:</strong> <code>DELETE FROM SanPham WHERE MaSP = 5</code> – xóa một hàng dữ liệu. <code>DROP TABLE SanPham</code> – xóa toàn bộ bảng (cả cấu trúc và dữ liệu) vĩnh viễn! Đây là lỗi tai hại trong production. Luôn confirm kỹ trước khi chạy DDL statements trong môi trường thật.</p><hr><h3 id="❌-loi-15-nghi-stored-procedure-la-tinh-nang-khong-can-thiet" tabindex="-1">❌ Lỗi 15: Nghĩ stored procedure là tính năng không cần thiết <a class="header-anchor" href="#❌-loi-15-nghi-stored-procedure-la-tinh-nang-khong-can-thiet" aria-label="Permalink to &quot;❌ Lỗi 15: Nghĩ stored procedure là tính năng không cần thiết&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tôi viết code trong ứng dụng, không cần stored procedure.&quot;</p><p><strong>Đúng:</strong> Stored procedure có ưu điểm: logic phức tạp chạy gần data (nhanh hơn gửi nhiều queries), reusable, có thể cấp quyền cho user gọi procedure mà không cần quyền trực tiếp trên bảng, và giảm network traffic. Hữu ích cho operations phức tạp và thường xuyên.</p><hr><h3 id="❌-loi-16-nham-view-voi-bang-that" tabindex="-1">❌ Lỗi 16: Nhầm view với bảng thật <a class="header-anchor" href="#❌-loi-16-nham-view-voi-bang-that" aria-label="Permalink to &quot;❌ Lỗi 16: Nhầm view với bảng thật&quot;">​</a></h3><p><strong>Sai:</strong> &quot;View là bảng được tối ưu hóa, lưu dữ liệu riêng.&quot;</p><p><strong>Đúng:</strong> View là <strong>câu lệnh SELECT đã được đặt tên và lưu</strong>. Khi query view, DBMS chạy SELECT đó với dữ liệu hiện tại. View không lưu dữ liệu riêng (ngoại trừ materialized view). Update dữ liệu gốc → view tự động reflect thay đổi.</p><hr><h3 id="❌-loi-17-cho-rang-tat-ca-dbms-đeu-dung-sql-giong-nhau" tabindex="-1">❌ Lỗi 17: Cho rằng tất cả DBMS đều dùng SQL giống nhau <a class="header-anchor" href="#❌-loi-17-cho-rang-tat-ca-dbms-đeu-dung-sql-giong-nhau" aria-label="Permalink to &quot;❌ Lỗi 17: Cho rằng tất cả DBMS đều dùng SQL giống nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;SQL viết cho MySQL chạy được trên PostgreSQL không cần chỉnh.&quot;</p><p><strong>Đúng:</strong> SQL có chuẩn ANSI, nhưng mỗi DBMS có dialect riêng: MySQL dùng LIMIT, SQL Server dùng TOP, Oracle dùng ROWNUM. Các hàm ngày tháng, concatenation, và nhiều tính năng khác khác nhau. Code SQL cần kiểm tra khi chuyển đổi DBMS.</p><hr><h3 id="❌-loi-18-nghi-table-khong-can-đat-ten-ro-rang" tabindex="-1">❌ Lỗi 18: Nghĩ table không cần đặt tên rõ ràng <a class="header-anchor" href="#❌-loi-18-nghi-table-khong-can-đat-ten-ro-rang" aria-label="Permalink to &quot;❌ Lỗi 18: Nghĩ table không cần đặt tên rõ ràng&quot;">​</a></h3><p><strong>Sai:</strong> Đặt tên bảng là <code>t1</code>, <code>data</code>, <code>info</code> cho ngắn.</p><p><strong>Đúng:</strong> Tên bảng và cột cần mô tả rõ ràng: <code>HocSinh</code>, <code>DiemHoc</code>, <code>MaHocSinh</code>. Quy tắc đặt tên nhất quán (snake_case hay CamelCase). Tên rõ ràng giúp: đọc hiểu schema dễ hơn, debug dễ hơn, và onboard người mới nhanh hơn.</p><hr><h3 id="❌-loi-19-nham-oltp-voi-olap" tabindex="-1">❌ Lỗi 19: Nhầm OLTP với OLAP <a class="header-anchor" href="#❌-loi-19-nham-oltp-voi-olap" aria-label="Permalink to &quot;❌ Lỗi 19: Nhầm OLTP với OLAP&quot;">​</a></h3><p><strong>Sai:</strong> &quot;CSDL của ứng dụng web tôi cũng dùng để báo cáo phân tích được.&quot;</p><p><strong>Đúng:</strong> OLTP (Online Transaction Processing): tối ưu cho read/write nhanh, nhiều transactions nhỏ – dùng cho ứng dụng. OLAP (Online Analytical Processing): tối ưu cho queries phức tạp trên data lớn – dùng cho Business Intelligence/reporting. Dùng OLTP cho OLAP queries sẽ chậm và ảnh hưởng production.</p><hr><h3 id="❌-loi-20-nghi-khong-can-kieu-du-lieu-chinh-xac" tabindex="-1">❌ Lỗi 20: Nghĩ không cần kiểu dữ liệu chính xác <a class="header-anchor" href="#❌-loi-20-nghi-khong-can-kieu-du-lieu-chinh-xac" aria-label="Permalink to &quot;❌ Lỗi 20: Nghĩ không cần kiểu dữ liệu chính xác&quot;">​</a></h3><p><strong>Sai:</strong> Lưu tất cả dữ liệu dạng <code>VARCHAR(255)</code> cho tiện.</p><p><strong>Đúng:</strong> Kiểu dữ liệu đúng quan trọng vì: <code>INT</code> chiếm ít dung lượng hơn <code>VARCHAR</code> cho số nguyên, <code>DATE</code> cho phép sort và tính khoảng thời gian đúng, <code>BOOLEAN</code> rõ ràng hơn <code>VARCHAR(&#39;true&#39;/&#39;false&#39;)</code>, và DBMS có thể enforce constraints đúng hơn.</p><hr><h3 id="❌-loi-21-nham-normalized-voi-denormalized" tabindex="-1">❌ Lỗi 21: Nhầm normalized với denormalized <a class="header-anchor" href="#❌-loi-21-nham-normalized-voi-denormalized" aria-label="Permalink to &quot;❌ Lỗi 21: Nhầm normalized với denormalized&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Denormalized là database bị lỗi normalization.&quot;</p><p><strong>Đúng:</strong> Denormalization là kỹ thuật có chủ đích: thêm redundancy để tăng read performance bằng cách tránh JOIN. Normalized: ít redundancy, dễ maintain, nhưng query cần nhiều JOIN. Denormalized: query nhanh hơn, nhưng tốn dung lượng và khó update. Chọn theo usecase.</p><hr><h3 id="❌-loi-22-cho-rang-moi-cot-đeu-nen-co-not-null" tabindex="-1">❌ Lỗi 22: Cho rằng mọi cột đều nên có NOT NULL <a class="header-anchor" href="#❌-loi-22-cho-rang-moi-cot-đeu-nen-co-not-null" aria-label="Permalink to &quot;❌ Lỗi 22: Cho rằng mọi cột đều nên có NOT NULL&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Không thích NULL nên đặt tất cả cột là NOT NULL với default value.&quot;</p><p><strong>Đúng:</strong> Không phải mọi cột đều có giá trị mặc định có ý nghĩa. Ví dụ: ngày kết hôn của học sinh chưa lập gia đình – NULL chính xác hơn là ngày 0001-01-01. NOT NULL nên dùng khi thực sự bắt buộc phải có giá trị. Suy nghĩ kỹ về business rules trước khi quyết định.</p><hr><h3 id="❌-loi-23-nghi-join-nhieu-bang-luon-cham" tabindex="-1">❌ Lỗi 23: Nghĩ join nhiều bảng luôn chậm <a class="header-anchor" href="#❌-loi-23-nghi-join-nhieu-bang-luon-cham" aria-label="Permalink to &quot;❌ Lỗi 23: Nghĩ join nhiều bảng luôn chậm&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Nên tránh JOIN vì chậm, copy data vào một bảng sẽ nhanh hơn.&quot;</p><p><strong>Đúng:</strong> JOIN trên indexed columns rất nhanh – đây là design cho phép. Tránh JOIN bằng cách denormalize có thể làm data không nhất quán. Query chậm thường do: thiếu index, viết query không tốt, hoặc data volume lớn – không phải do JOIN về nguyên tắc.</p><hr><h3 id="❌-loi-24-nham-database-server-voi-web-server" tabindex="-1">❌ Lỗi 24: Nhầm database server với web server <a class="header-anchor" href="#❌-loi-24-nham-database-server-voi-web-server" aria-label="Permalink to &quot;❌ Lỗi 24: Nhầm database server với web server&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Database server và web server là cùng một máy, không cần tách.&quot;</p><p><strong>Đúng:</strong> Trong production, nên tách database server riêng: bảo mật (DB không expose trực tiếp ra Internet), hiệu suất (resources không cạnh tranh), và scalability (scale DB riêng khi cần). Development thì ổn khi dùng cùng máy, production thì nên tách.</p><hr><h3 id="❌-loi-25-cho-rang-password-database-khong-can-manh" tabindex="-1">❌ Lỗi 25: Cho rằng password database không cần mạnh <a class="header-anchor" href="#❌-loi-25-cho-rang-password-database-khong-can-manh" aria-label="Permalink to &quot;❌ Lỗi 25: Cho rằng password database không cần mạnh&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Database chỉ trong mạng nội bộ, dùng mật khẩu đơn giản được.&quot;</p><p><strong>Đúng:</strong> Database credentials cần mạnh vì: SQL injection có thể bypass network protection, insider threats, và lateral movement sau khi attacker vào mạng nội bộ. Dùng strong password, principle of least privilege (mỗi ứng dụng chỉ có quyền cần thiết), và không hardcode credentials trong code.</p><hr><h3 id="❌-loi-26-nghi-csdl-khong-can-document" tabindex="-1">❌ Lỗi 26: Nghĩ CSDL không cần document <a class="header-anchor" href="#❌-loi-26-nghi-csdl-khong-can-document" aria-label="Permalink to &quot;❌ Lỗi 26: Nghĩ CSDL không cần document&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Schema dễ hiểu, không cần viết tài liệu.&quot;</p><p><strong>Đúng:</strong> Database documentation quan trọng: mô tả ý nghĩa của từng bảng và cột, business rules được implement, và lý do thiết kế. Schema có thể đọc nhưng business context không tự hiểu từ tên cột. Comment trong SQL và ERD diagram giúp onboarding và maintenance.</p><hr><h3 id="❌-loi-27-nham-soft-delete-voi-hard-delete" tabindex="-1">❌ Lỗi 27: Nhầm soft delete với hard delete <a class="header-anchor" href="#❌-loi-27-nham-soft-delete-voi-hard-delete" aria-label="Permalink to &quot;❌ Lỗi 27: Nhầm soft delete với hard delete&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Xóa dữ liệu = DELETE SQL statement.&quot;</p><p><strong>Đúng:</strong> Soft delete: thêm cột <code>IsDeleted = 1</code> thay vì xóa thật. Giữ lại audit trail, có thể phục hồi, và tránh cascade delete issues. Hard delete: xóa thật bằng DELETE. Nhiều hệ thống quan trọng dùng soft delete vì regulatory requirements và audit purposes.</p><hr><h3 id="❌-loi-28-cho-rang-tat-ca-du-lieu-phai-luu-trong-csdl-quan-he" tabindex="-1">❌ Lỗi 28: Cho rằng tất cả dữ liệu phải lưu trong CSDL quan hệ <a class="header-anchor" href="#❌-loi-28-cho-rang-tat-ca-du-lieu-phai-luu-trong-csdl-quan-he" aria-label="Permalink to &quot;❌ Lỗi 28: Cho rằng tất cả dữ liệu phải lưu trong CSDL quan hệ&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mọi dữ liệu đều nên lưu trong MySQL/PostgreSQL.&quot;</p><p><strong>Đúng:</strong> Không phải tất cả data phù hợp với relational model: ảnh/video → file storage (S3, MinIO), session data → Redis (key-value store), log data → Elasticsearch hoặc time-series DB, social graph → Neo4j. Dùng đúng tool cho đúng job.</p><hr><h3 id="❌-loi-29-nghi-acid-la-tinh-nang-cua-moi-dbms" tabindex="-1">❌ Lỗi 29: Nghĩ ACID là tính năng của mọi DBMS <a class="header-anchor" href="#❌-loi-29-nghi-acid-la-tinh-nang-cua-moi-dbms" aria-label="Permalink to &quot;❌ Lỗi 29: Nghĩ ACID là tính năng của mọi DBMS&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mọi database đều đảm bảo ACID transactions.&quot;</p><p><strong>Đúng:</strong> ACID là tính năng của nhiều RDBMS, nhưng nhiều NoSQL databases hy sinh một phần ACID để đổi lấy scalability. MongoDB mặc định không có multi-document ACID (nhưng có thể bật). Cassandra chọn Availability &gt; Consistency (BASE model). Hiểu CAP theorem để chọn DBMS đúng.</p><hr><h3 id="❌-loi-30-nham-foreign-key-constraint-voi-join" tabindex="-1">❌ Lỗi 30: Nhầm foreign key constraint với join <a class="header-anchor" href="#❌-loi-30-nham-foreign-key-constraint-voi-join" aria-label="Permalink to &quot;❌ Lỗi 30: Nhầm foreign key constraint với join&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Không cần foreign key constraint, JOIN vẫn chạy được.&quot;</p><p><strong>Đúng:</strong> JOIN chạy không cần FK constraint, nhưng FK constraint đảm bảo referential integrity: không thể có order với customer_id không tồn tại trong bảng customers. Thiếu FK constraint → orphan records (dữ liệu &quot;mồ côi&quot; trỏ đến row không tồn tại), gây lỗi logic khó tìm.</p><hr><h3 id="❌-loi-31-cho-rang-database-size-khong-quan-trong" tabindex="-1">❌ Lỗi 31: Cho rằng database size không quan trọng <a class="header-anchor" href="#❌-loi-31-cho-rang-database-size-khong-quan-trong" aria-label="Permalink to &quot;❌ Lỗi 31: Cho rằng database size không quan trọng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dung lượng ổ đĩa rẻ, database lớn cũng không sao.&quot;</p><p><strong>Đúng:</strong> Database size ảnh hưởng đến: backup/restore time, query performance (scan nhiều data hơn), và replication lag. Data retention policy: xóa hoặc archive dữ liệu cũ không cần thiết (logs, sessions hết hạn). Archiving sang cold storage cho data ít dùng.</p><hr><h3 id="❌-loi-32-nghi-khong-can-monitoring-csdl" tabindex="-1">❌ Lỗi 32: Nghĩ không cần monitoring CSDL <a class="header-anchor" href="#❌-loi-32-nghi-khong-can-monitoring-csdl" aria-label="Permalink to &quot;❌ Lỗi 32: Nghĩ không cần monitoring CSDL&quot;">​</a></h3><p><strong>Sai:</strong> &quot;CSDL hoạt động thì không cần theo dõi.&quot;</p><p><strong>Đúng:</strong> Database monitoring phát hiện sớm: slow queries (tự động xuất hiện khi data tăng), connection pool exhaustion, disk space nearing limit, và replication lag. Tools: MySQL slow query log, pg_stat_statements, Prometheus + Grafana. Proactive hơn là reactive.</p><hr><h3 id="❌-loi-33-nham-table-lock-voi-row-lock" tabindex="-1">❌ Lỗi 33: Nhầm table lock với row lock <a class="header-anchor" href="#❌-loi-33-nham-table-lock-voi-row-lock" aria-label="Permalink to &quot;❌ Lỗi 33: Nhầm table lock với row lock&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mọi operation trên bảng đều lock cả bảng.&quot;</p><p><strong>Đúng:</strong> RDBMS hiện đại dùng row-level locking để tăng concurrency. Chỉ lock row đang được modify, không lock toàn bảng. Table lock xảy ra với DDL statements (ALTER TABLE) hoặc explicit LOCK TABLE. Hiểu locking giúp debug deadlock và optimize concurrent access.</p><hr><h3 id="❌-loi-34-cho-rang-replication-la-backup" tabindex="-1">❌ Lỗi 34: Cho rằng replication là backup <a class="header-anchor" href="#❌-loi-34-cho-rang-replication-la-backup" aria-label="Permalink to &quot;❌ Lỗi 34: Cho rằng replication là backup&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dùng database replication rồi không cần backup.&quot;</p><p><strong>Đúng:</strong> Replication đồng bộ changes sang replica – nếu xóa nhầm dữ liệu, xóa nhầm đó sẽ replicat sang tất cả replicas. Replication giúp high availability (failover nhanh), không phải disaster recovery. Cần cả replication lẫn point-in-time backup cho protection toàn diện.</p><hr><h3 id="❌-loi-35-nghi-query-chay-đung-la-query-chay-tot" tabindex="-1">❌ Lỗi 35: Nghĩ query chạy đúng là query chạy tốt <a class="header-anchor" href="#❌-loi-35-nghi-query-chay-đung-la-query-chay-tot" aria-label="Permalink to &quot;❌ Lỗi 35: Nghĩ query chạy đúng là query chạy tốt&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Query trả về kết quả đúng là đủ, không cần optimize.&quot;</p><p><strong>Đúng:</strong> Query trả về đúng nhưng dùng <code>SELECT *</code> thay vì select cụ thể cột cần thiết, hay full table scan thay vì dùng index, sẽ chậm và tốn resource khi scale. EXPLAIN/EXPLAIN ANALYZE cho thấy execution plan – cần học để optimize queries quan trọng.</p><hr><h3 id="❌-loi-36-nham-sql-injection-voi-loi-syntax-sql" tabindex="-1">❌ Lỗi 36: Nhầm SQL injection với lỗi syntax SQL <a class="header-anchor" href="#❌-loi-36-nham-sql-injection-voi-loi-syntax-sql" aria-label="Permalink to &quot;❌ Lỗi 36: Nhầm SQL injection với lỗi syntax SQL&quot;">​</a></h3><p><strong>Sai:</strong> &quot;SQL injection là lỗi trong code SQL của developer.&quot;</p><p><strong>Đúng:</strong> SQL injection là tấn công bảo mật: kẻ tấn công nhập SQL code vào form input để thao túng query. <code>SELECT * FROM users WHERE name = &#39;&#39; OR &#39;1&#39;=&#39;1&#39;</code> – bypass authentication. Phòng ngừa: dùng parameterized queries/prepared statements, KHÔNG nối string trực tiếp vào query.</p><hr><h3 id="❌-loi-37-cho-rang-stored-procedure-an-toan-hon-inline-sql" tabindex="-1">❌ Lỗi 37: Cho rằng stored procedure an toàn hơn inline SQL <a class="header-anchor" href="#❌-loi-37-cho-rang-stored-procedure-an-toan-hon-inline-sql" aria-label="Permalink to &quot;❌ Lỗi 37: Cho rằng stored procedure an toàn hơn inline SQL&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dùng stored procedure thay vì inline SQL là đủ để tránh SQL injection.&quot;</p><p><strong>Đúng:</strong> Stored procedure cũng bị SQL injection nếu dùng dynamic SQL bên trong (EXEC hoặc sp_executesql với string concatenation). An toàn không đến từ stored procedure vs inline SQL, mà từ parameterized queries (tách code và data).</p><hr><h3 id="❌-loi-38-nghi-triggers-la-giai-phap-tot-nhat-cho-business-logic" tabindex="-1">❌ Lỗi 38: Nghĩ triggers là giải pháp tốt nhất cho business logic <a class="header-anchor" href="#❌-loi-38-nghi-triggers-la-giai-phap-tot-nhat-cho-business-logic" aria-label="Permalink to &quot;❌ Lỗi 38: Nghĩ triggers là giải pháp tốt nhất cho business logic&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Trigger là cách tốt nhất để enforce business rules trong CSDL.&quot;</p><p><strong>Đúng:</strong> Trigger hữu ích cho: audit logging, automatic timestamp updates, và một số data integrity checks. Nhưng overuse triggers: khó debug (logic ẩn, không thấy trong application code), khó test, và gây performance issues. Business logic quan trọng thường tốt hơn ở application layer.</p><hr><h3 id="❌-loi-39-nham-full-text-search-voi-like-query" tabindex="-1">❌ Lỗi 39: Nhầm full-text search với LIKE query <a class="header-anchor" href="#❌-loi-39-nham-full-text-search-voi-like-query" aria-label="Permalink to &quot;❌ Lỗi 39: Nhầm full-text search với LIKE query&quot;">​</a></h3><p><strong>Sai:</strong> <code>WHERE description LIKE &#39;%keyword%&#39;</code> là đủ cho tìm kiếm văn bản.&quot;</p><p><strong>Đúng:</strong> LIKE với % ở đầu không dùng index (full table scan), chậm với data lớn, và không hỗ trợ: stemming, relevance ranking, fuzzy matching. Full-text search (MySQL FULLTEXT, PostgreSQL tsvector) hoặc dedicated search engine (Elasticsearch) cho kết quả tốt hơn nhiều cho search functionality.</p><hr><h3 id="❌-loi-40-cho-rang-auto-increment-id-la-giai-phap-primary-key-duy-nhat" tabindex="-1">❌ Lỗi 40: Cho rằng auto-increment ID là giải pháp Primary Key duy nhất <a class="header-anchor" href="#❌-loi-40-cho-rang-auto-increment-id-la-giai-phap-primary-key-duy-nhat" aria-label="Permalink to &quot;❌ Lỗi 40: Cho rằng auto-increment ID là giải pháp Primary Key duy nhất&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Primary Key luôn phải là số nguyên auto-increment.&quot;</p><p><strong>Đúng:</strong> Các loại PK: Auto-increment INT (simple, phổ biến), UUID/GUID (globally unique – tốt cho distributed systems), Natural Key (dùng business data như email – nguy hiểm nếu email thay đổi), và Composite Key (kết hợp nhiều cột). Chọn theo yêu cầu hệ thống.</p><hr><h3 id="❌-loi-41-nghi-varchar-255-va-varchar-50-chiem-cung-dung-luong" tabindex="-1">❌ Lỗi 41: Nghĩ VARCHAR(255) và VARCHAR(50) chiếm cùng dung lượng <a class="header-anchor" href="#❌-loi-41-nghi-varchar-255-va-varchar-50-chiem-cung-dung-luong" aria-label="Permalink to &quot;❌ Lỗi 41: Nghĩ VARCHAR(255) và VARCHAR(50) chiếm cùng dung lượng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;VARCHAR(255) và VARCHAR(50) chiếm cùng bộ nhớ nên cứ dùng 255 cho rộng.&quot;</p><p><strong>Đúng:</strong> VARCHAR chỉ dùng dung lượng thực tế + 1-2 bytes lưu độ dài. VARCHAR(255) không tốn nhiều hơn VARCHAR(50) nếu data thực tế cùng dài. Nhưng khai báo độ dài phù hợp: DBMS có thể dùng thông tin này để optimize, và là documentation về business rules.</p><hr><h3 id="❌-loi-42-nham-connection-pool-voi-database-connection" tabindex="-1">❌ Lỗi 42: Nhầm connection pool với database connection <a class="header-anchor" href="#❌-loi-42-nham-connection-pool-voi-database-connection" aria-label="Permalink to &quot;❌ Lỗi 42: Nhầm connection pool với database connection&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mỗi request tạo một database connection mới là bình thường.&quot;</p><p><strong>Đúng:</strong> Tạo/đóng connection cho mỗi request rất tốn kém (handshake, authentication). Connection pool tái sử dụng connections. Không dùng connection pool → bottleneck nghiêm trọng khi nhiều concurrent users. Tất cả ORM và database drivers hiện đại có connection pooling – cần configure đúng.</p><hr><h3 id="❌-loi-43-cho-rang-csdl-khong-can-encryption" tabindex="-1">❌ Lỗi 43: Cho rằng CSDL không cần encryption <a class="header-anchor" href="#❌-loi-43-cho-rang-csdl-khong-can-encryption" aria-label="Permalink to &quot;❌ Lỗi 43: Cho rằng CSDL không cần encryption&quot;">​</a></h3><p><strong>Sai:</strong> &quot;CSDL trong server nội bộ không cần encryption.&quot;</p><p><strong>Đúng:</strong> Encryption at rest bảo vệ khi: ổ cứng server bị đánh cắp vật lý, backup bị compromise, hoặc cloud storage breach. Transparent Data Encryption (TDE) trong SQL Server, encrypted tablespaces trong PostgreSQL. Dữ liệu nhạy cảm (PII, password, payment info) đặc biệt cần encryption.</p><hr><h3 id="❌-loi-44-nghi-cascade-delete-luon-la-giai-phap-tot" tabindex="-1">❌ Lỗi 44: Nghĩ Cascade Delete luôn là giải pháp tốt <a class="header-anchor" href="#❌-loi-44-nghi-cascade-delete-luon-la-giai-phap-tot" aria-label="Permalink to &quot;❌ Lỗi 44: Nghĩ Cascade Delete luôn là giải pháp tốt&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Đặt ON DELETE CASCADE cho tất cả Foreign Keys cho tiện.&quot;</p><p><strong>Đúng:</strong> Cascade Delete tự động xóa related rows khi xóa parent – nguy hiểm nếu không cẩn thận. Xóa nhầm một customer → xóa hết orders, payments, reviews! Cân nhắc: ON DELETE RESTRICT (chặn xóa nếu còn children), ON DELETE SET NULL, hoặc soft delete. Chỉ dùng CASCADE khi chắc chắn muốn cascade behavior.</p><hr><h3 id="❌-loi-45-nham-database-migration-voi-data-migration" tabindex="-1">❌ Lỗi 45: Nhầm database migration với data migration <a class="header-anchor" href="#❌-loi-45-nham-database-migration-voi-data-migration" aria-label="Permalink to &quot;❌ Lỗi 45: Nhầm database migration với data migration&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Database migration và data migration là như nhau.&quot;</p><p><strong>Đúng:</strong> Database/schema migration: thay đổi cấu trúc CSDL (thêm cột, đổi kiểu dữ liệu, tạo index). Data migration: di chuyển dữ liệu từ hệ thống này sang hệ thống khác. Schema migration tools (Flyway, Liquibase, Alembic) giúp version control thay đổi schema.</p><hr><h3 id="❌-loi-46-cho-rang-tat-ca-database-queries-la-idempotent" tabindex="-1">❌ Lỗi 46: Cho rằng tất cả database queries là idempotent <a class="header-anchor" href="#❌-loi-46-cho-rang-tat-ca-database-queries-la-idempotent" aria-label="Permalink to &quot;❌ Lỗi 46: Cho rằng tất cả database queries là idempotent&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Chạy query nhiều lần cũng không sao.&quot;</p><p><strong>Đúng:</strong> SELECT luôn idempotent. Nhưng INSERT thêm row mỗi lần chạy – chạy nhiều lần tạo duplicate data. UPSERT (INSERT ... ON DUPLICATE KEY UPDATE hoặc MERGE) là idempotent. Quan trọng khi: retry logic trong distributed systems, migration scripts, và batch processing.</p><hr><h3 id="❌-loi-47-nghi-khong-can-biet-execution-plan" tabindex="-1">❌ Lỗi 47: Nghĩ không cần biết execution plan <a class="header-anchor" href="#❌-loi-47-nghi-khong-can-biet-execution-plan" aria-label="Permalink to &quot;❌ Lỗi 47: Nghĩ không cần biết execution plan&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Developer không cần hiểu execution plan, đó là việc của DBA.&quot;</p><p><strong>Đúng:</strong> Mọi developer viết SQL cần hiểu cơ bản về execution plan để: nhận ra full table scan, hiểu tại sao query chậm, và biết khi nào cần index. <code>EXPLAIN</code> trong MySQL/PostgreSQL/SQLite là công cụ thiết yếu. Performance issue thường có thể giải quyết bằng query rewrite hoặc thêm index.</p><hr><h3 id="❌-loi-48-nham-sharding-voi-replication" tabindex="-1">❌ Lỗi 48: Nhầm sharding với replication <a class="header-anchor" href="#❌-loi-48-nham-sharding-voi-replication" aria-label="Permalink to &quot;❌ Lỗi 48: Nhầm sharding với replication&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Sharding và replication đều là cách scale database.&quot;</p><p><strong>Đúng:</strong> Replication: copy toàn bộ data sang nhiều servers – scale reads, high availability, failover. Sharding: chia data thành partitions trên nhiều servers – scale writes và storage khi data quá lớn cho một server. Khái niệm rất khác nhau, giải quyết vấn đề khác nhau.</p><hr><h3 id="❌-loi-49-cho-rang-stored-data-validation-la-khong-can-thiet" tabindex="-1">❌ Lỗi 49: Cho rằng stored data validation là không cần thiết <a class="header-anchor" href="#❌-loi-49-cho-rang-stored-data-validation-la-khong-can-thiet" aria-label="Permalink to &quot;❌ Lỗi 49: Cho rằng stored data validation là không cần thiết&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Application đã validate input, CSDL không cần constraints.&quot;</p><p><strong>Đúng:</strong> Defense in depth: application có thể có bug, direct DB access bypass application, và bug trong future code có thể insert invalid data. Database constraints (NOT NULL, UNIQUE, CHECK, FK) là last line of defense. Cả hai layers validation đều cần thiết.</p><hr><h3 id="❌-loi-50-nghi-data-type-enum-la-tot-nhat-cho-categorical-data" tabindex="-1">❌ Lỗi 50: Nghĩ data type ENUM là tốt nhất cho categorical data <a class="header-anchor" href="#❌-loi-50-nghi-data-type-enum-la-tot-nhat-cho-categorical-data" aria-label="Permalink to &quot;❌ Lỗi 50: Nghĩ data type ENUM là tốt nhất cho categorical data&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dùng ENUM cho cột status là cách tốt nhất.&quot;</p><p><strong>Đúng:</strong> ENUM có nhược điểm: thêm value mới vào ENUM cần ALTER TABLE (trong MySQL cũ, đây là full table rebuild), ENUM values thường hardcode trong schema. Cách tốt hơn thường là: lookup table riêng (bảng Status với StatusID và StatusName) – linh hoạt hơn, có thể thêm value không cần ALTER TABLE.</p>',282)])])}const p=t(h,[["render",e]]);export{u as __pageData,p as default};
